using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEngine.Profiling;
public static class RebirthCamperTextureBudget {
 const string Prefab="Assets/REBIRTHCamperFrontProfile_20261015_v7/rebirthCamper80s.prefab";
 const string Output="E:/_Haven/shared/REBIRTHTemp/CamperTextureBudget_20261015";
 static string Hash(string p){using(var f=File.OpenRead(p))using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(f)).Replace("-","");}
 static bool Station(Transform t){return t.GetComponentsInParent<Transform>(true).Any(x=>x.name=="REBIRTHCampRoofStations"||x.name=="REBIRTHCampInteriorStations"||x.name=="REBIRTHCampPowerEquipment");}
 public static void Run(){Directory.CreateDirectory(Output);var root=AssetDatabase.LoadAssetAtPath<GameObject>(Prefab);if(!root)throw new Exception("Source missing");var textures=new Dictionary<string,int>();var roles=new Dictionary<string,string>();var inventory=new List<string>{"renderer\tmaterial\tproperty\tpath\twidth\theight\tformat\tbytes\tstation"};
 foreach(var r in root.GetComponentsInChildren<Renderer>(true))foreach(var m in r.sharedMaterials.Where(m=>m))foreach(var key in m.GetTexturePropertyNames()){var tex=m.GetTexture(key) as Texture2D;if(!tex)continue;var p=AssetDatabase.GetAssetPath(tex);bool station=Station(r.transform);inventory.Add(r.name+"\t"+m.name+"\t"+key+"\t"+p+"\t"+tex.width+"\t"+tex.height+"\t"+tex.format+"\t"+Profiler.GetRuntimeMemorySizeLong(tex)+"\t"+station);if(!station)continue;int size=key=="_MainTex"||key=="_BumpMap"?1024:key=="_MetallicGlossMap"?256:0;if(size==0)throw new Exception("Unbudgeted station map "+key+" "+p);if(textures.ContainsKey(p)&&textures[p]!=size)throw new Exception("Conflicting map role "+p);textures[p]=size;roles[p]=key;}
 File.WriteAllLines(Output+"/inventory-before.tsv",inventory);var receipt=new List<string>{"path\trole\tmaxSize\tactualWidth\tactualHeight\tformat\tcrunch\tsourceSHA256"};
 foreach(var pair in textures){string p=pair.Key,hash=Hash(p);var i=AssetImporter.GetAtPath(p) as TextureImporter;if(!i)throw new Exception("Texture importer missing "+p);File.Copy(p+".meta",Output+"/"+AssetDatabase.AssetPathToGUID(p)+".before.meta",true);i.maxTextureSize=pair.Value;i.textureCompression=TextureImporterCompression.CompressedHQ;i.crunchedCompression=true;i.compressionQuality=90;var platform=i.GetPlatformTextureSettings("Standalone");platform.name="Standalone";platform.overridden=true;platform.maxTextureSize=pair.Value;platform.format=roles[p]=="_MainTex"&&!i.DoesSourceTextureHaveAlpha()?TextureImporterFormat.DXT1Crunched:TextureImporterFormat.DXT5Crunched;platform.textureCompression=TextureImporterCompression.CompressedHQ;platform.crunchedCompression=true;platform.compressionQuality=90;i.SetPlatformTextureSettings(platform);i.SaveAndReimport();if(Hash(p)!=hash)throw new Exception("Original image changed "+p);var t=AssetDatabase.LoadAssetAtPath<Texture2D>(p);if(t.width>pair.Value||t.height>pair.Value)throw new Exception("Size cap failed "+p);receipt.Add(p+"\t"+roles[p]+"\t"+pair.Value+"\t"+t.width+"\t"+t.height+"\t"+t.format+"\ttrue\t"+hash);}
 AssetDatabase.SaveAssets();File.WriteAllLines(Output+"/verified.tsv",receipt);File.WriteAllText(Output+"/verified.txt","PASS "+textures.Count+" unique referenced station textures; albedo/normal1024, metallic-smoothness256; source image hashes unchanged; Standalone Crunch90. No installed assets changed. Camper inventory in inventory-before.tsv. Bundle must be rebuilt and reopened separately.");}
}
